create schema rich;
create type rich.point3 as (x float8, y float8, z float8);
create type rich.segment as (a rich.point3, b rich.point3, tags text[]);
create function rich.f8diff(a float8, b float8) returns float8 language sql immutable as 'select a - b';
create type rich.f8range as range (subtype = float8, subtype_diff = rich.f8diff);
create domain rich.small_tags as text[] check (cardinality(value) <= 3);
create function rich.add(a int, b int default 1) returns int language sql immutable as 'select a + b';
create function rich.add(a numeric, b numeric) returns numeric language sql immutable as 'select a + b';
create function rich.sum_all(variadic xs int[]) returns int language sql immutable as 'select coalesce(sum(x), 0)::int from unnest(xs) x';
create function rich.pairs(n int) returns table (i int, sq int) language sql stable rows 10 as 'select g, g * g from generate_series(1, n) g';
create procedure rich.bump(inout counter int, step int default 1) language plpgsql as $$ begin counter := counter + step; end $$;
create function rich.avg_state(st numeric[], v numeric) returns numeric[] language sql immutable strict as 'select array[st[1] + v, st[2] + 1]';
create function rich.avg_combine(a numeric[], b numeric[]) returns numeric[] language sql immutable strict as 'select array[a[1] + b[1], a[2] + b[2]]';
create function rich.avg_final(st numeric[]) returns numeric language sql immutable as 'select case when st[2] = 0 then null else st[1] / st[2] end';
create aggregate rich.my_avg(numeric) (sfunc = rich.avg_state, stype = numeric[], initcond = '{0,0}', finalfunc = rich.avg_final, combinefunc = rich.avg_combine, parallel = safe);
create collation rich.ci (provider = icu, locale = 'und-u-ks-level2', deterministic = false);
create text search configuration rich.english_simple (copy = pg_catalog.english);
alter text search configuration rich.english_simple alter mapping for asciiword with simple;
create table rich.item (id int primary key, name text collate rich.ci not null, kind text, price numeric, seg rich.segment, span rich.f8range, tags rich.small_tags);
create statistics rich.item_stats (ndistinct, dependencies) on kind, lower(name) from rich.item;
create table rich.tree (id int primary key, parent int references rich.tree);
create view rich.tree_paths as with recursive p(id, path) as (select id, array[id] from rich.tree where parent is null union all select t.id, p.path || t.id from rich.tree t join p on t.parent = p.id) select * from p;
create view rich.cheap as select id, name, price from rich.item where price < 10 with local check option;
create rule cheap_delete as on delete to rich.cheap do instead update rich.item set price = 10 where id = old.id;
create function rich.on_ddl() returns event_trigger language plpgsql as $$ begin raise notice 'ddl'; end $$;
create event trigger rich_ddl on ddl_command_end when tag in ('CREATE TABLE', 'ALTER TABLE') execute function rich.on_ddl();
create table rich.base (id int, note text);
create table rich.child (extra int) inherits (rich.base);
